1	// Import necessary types and utilities
2	import { type Result, type EngineOutput, type YaoState } from './core/models.js';
3	import { SovereignDomain, DOMAIN_ADJACENCY } from './types/SovereignDomain.js';
4	import { createLogger } from "./utils/logger.js";
5	
6	const logger = createLogger('ToolRegistry');
7	
8	/**
9	 * Defines the structure for a sovereign tool, including its metadata, domain,
10	 * and execution parameters. All properties are readonly to ensure immutability
11	 * once a tool definition is created.
12	 */
13	export interface ToolDefinition {
14	    readonly name: string;
15	    readonly description: string;
16	    readonly humanDescription?: string;      // High-level explanation for non-specialists
17	    readonly jargonDescription?: string;     // Technical, low-level explanation
18	    readonly idealYaoState?: YaoState;       // Preferred metabolic state for execution
19	    readonly domain: SovereignDomain;
20	    readonly category?: 'core' | 'filesystem' | 'network' | 'ai' | 'mcp' | 'sensory' | 'forge' | 'literary' | 'creative' | 'vscode';
21	    readonly parameters: Readonly<Record<string, unknown>>; // Parameters are part of the definition and should be immutable
22	    readonly execute: (args: Readonly<Record<string, unknown>>) => Promise<Result<EngineOutput>>; // The execution function itself is part of the definition
23	}
24	
25	/**
26	 * ToolRegistry â€” Sovereign capability substrate with domain scoping.
27	 * Phase 18: Refined tool organization and category-based filtering.
28	 * Manages the registration, retrieval, and filtering of ToolDefinitions.
29	 */
30	export class ToolRegistry {
31	    private readonly tools: Map<string, ToolDefinition> = new Map();
32	
33	    /**
34	     * Register a tool with the sovereign substrate.
35	     * @param tool The ToolDefinition to register.
36	     */
37	    public register(tool: ToolDefinition): void {
38	        this.tools.set(tool.name, tool);
39	        logger.debug({ tool: tool.name, domain: tool.domain, category: tool.category }, 'Tool registered');
40	    }
41	
42	    /**
43	     * Retrieve a tool by name (case-insensitive and format-agnostic).
44	     * Normalizes the input name and registered tool names for robust lookup.
45	     * @param name The name of the tool to retrieve.
46	     * @returns The ToolDefinition if found, otherwise undefined.
47	     */
48	    public getTool(name: string): ToolDefinition | undefined {
49	        const exact = this.tools.get(name);
50	        if (exact) return exact;
51	
52	        const normalized = name.toLowerCase().replace(/[_-\s]/g, '');
53	        for (const [key, tool] of this.tools.entries()) {
54	            if (key.toLowerCase().replace(/[_-\s]/g, '') === normalized) {
55	                return tool;
56	            }
57	        }
58	        return undefined;
59	    }
60	
61	    /**
62	     * Get all registered tool definitions.
63	     * @returns An array of all registered ToolDefinitions.
64	     */
65	    public getDefinitions(): ToolDefinition[] {
66	        return Array.from(this.tools.values());
67	    }
68	
69	    /**
70	     * Get tools scoped to a specific domain, including tools from adjacent domains
71	     * as defined by DOMAIN_ADJACENCY.
72	     * @param domain The primary domain for which to retrieve tools.
73	     * @returns An array of ToolDefinitions relevant to the specified domain and its adjacencies.
74	     */
75	    public getToolsForDomain(domain: SovereignDomain): ToolDefinition[] {
76	        const allowedDomains = DOMAIN_ADJACENCY[domain];
77	        if (!allowedDomains) {
78	            logger.warn({ domain }, 'No adjacency mapping found for domain. Returning empty array.');
79	            return [];
80	        }
81	        return this.getDefinitions().filter((t: ToolDefinition) => allowedDomains.has(t.domain));
82	    }
83	
84	    /**
85	     * Get tools by a specific category.
86	     * @param category The category string to filter tools by.
87	     * @returns An array of ToolDefinitions belonging to the specified category.
88	     */
89	    public getToolsByCategory(category: string): ToolDefinition[] {
90	        return this.getDefinitions().filter((t: ToolDefinition) => t.category === category);
91	    }
92	
93	    /**
94	     * Get formatted definitions for ALL tools (unscoped), suitable for human readability.
95	     * @returns A string containing a newline-separated list of formatted tool descriptions.
96	     */
97	    public getFormattedDefinitions(): string {
98	        return this.getDefinitions()
99	            .map((t: ToolDefinition) => `- ${t.name} [${t.domain}${t.category ? `:${t.category}` : ''}]: ${t.description}`)
100	            .join('\n');
101	    }
102	
103	    /**
104	     * Get formatted definitions scoped to a domain for LLM context.
105	     * Includes tool name, description, and JSON-stringified parameters.
106	     * @param domain The domain to scope the formatted definitions to.
107	     * @returns A string containing a newline-separated list of formatted tool descriptions for LLM consumption.
108	     */
109	    public getFormattedDefinitionsForDomain(domain: SovereignDomain): string {
110	        return this.getToolsForDomain(domain)
111	            .map((t: ToolDefinition) => `- ${t.name}: ${t.description}. Params: ${JSON.stringify(t.parameters)}`)
112	            .join('\n');
113	    }
114	
115	    /**
116	     * Get the domain for a specific tool.
117	     * @param toolName The name of the tool.
118	     * @returns The SovereignDomain of the tool if found, otherwise undefined.
119	     */
120	    public getToolDomain(toolName: string): SovereignDomain | undefined {
121	        return this.getTool(toolName)?.domain;
122	    }
123	
124	    /**
125	     * Get all registered tool names.
126	     * @returns An array of strings, each representing the name of a registered tool.
127	     */
128	    public getToolNames(): string[] {
129	        return Array.from(this.tools.keys());
130	    }
131	}
